SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "追叙唐末以来贩卖告身、紊乱昭穆与选人冒滥现象。", "citation": "卷273·同光二年（924）·zztj-v273-y0924-p025·原文件第30行", "note": "原文：自唐末丧乱，搢绅之家或以告赤鬻于族姻，遂乱昭穆，至有舅叔拜甥、侄者，选人伪滥者众。；核对说明：告赤疑告敕字，底本不改，依后文告身和新史告敕释为任官文书；舅叔拜甥侄是作者例说，无名对象不建假亲属。", "status": "draft", "id": "e67f956d-e3bd-5ebc-a09f-589b88b59908", "subject_id": "de636664-2803-52b0-9b5a-a18b62edeed7", "source_id": "4b544209-f219-5bbb-9d34-a8994528c12b"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "唐末以来持续背景，确年未载", "citation": "卷273·同光二年（924）·zztj-v273-y0924-p025·原文件第30行", "note": "原文：自唐末丧乱，搢绅之家或以告赤鬻于族姻，遂乱昭穆，至有舅叔拜甥、侄者，选人伪滥者众。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "b9d87acf-e8ac-5d31-a846-f7f24d77f12d", "subject_id": "de636664-2803-52b0-9b5a-a18b62edeed7", "source_id": "4b544209-f219-5bbb-9d34-a8994528c12b"}, {"subject_table": "event", "field_path": "description", "claim_text": "新史亦记吏部文书不完、私鬻告敕、乱易昭穆。", "citation": "《新五代史》卷二十八，段落 xin-wudaishi-b08f244b9241-p000994；EPUB电子本，纸本及异文待核", "note": "原文：而吏部銓文書不完，因緣以為姦利，至有私鬻告敕，亂易昭穆，；核对说明：释主书疑字用独立出处；后续冬案人物不抢录。", "status": "draft", "id": "20b4896d-250a-5ad0-9263-9b2c076aa8e0", "subject_id": "de636664-2803-52b0-9b5a-a18b62edeed7", "source_id": "8e545bf3-b738-56e1-9bea-922453b3c664"}, {"subject_table": "event", "field_path": "description", "claim_text": "郭崇韬请铨司考核，南郊行事官多被毁告身，主书记选人困顿。", "citation": "卷273·同光二年（924）·zztj-v273-y0924-p025·原文件第30行", "note": "原文：郭崇韬欲革其弊，请令铨司精加考核。时南郊行事官千二百人，注官者才数十人，涂毁告身者十之九。选人或号哭道路，或馁死逆旅。；核对说明：千二百、数十、十之九为主书约数，不能以约数相减生成精确落选人数；号哭馁死为作者描述。", "status": "draft", "id": "b98dea16-a00f-5b25-a14f-bb424ef339d0", "subject_id": "6a70a649-35d0-51b0-b0f3-a235961fb21c", "source_id": "4b544209-f219-5bbb-9d34-a8994528c12b"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "924年三月本段；具体考核日未载", "citation": "卷273·同光二年（92